'use client';

import React, { useState, useMemo } from 'react';
import { AppSidebar } from '@/components/AppSidebar';
import { AppTopBar } from '@/components/AppTopBar';
import { OverviewDashboard } from '@/components/OverviewDashboard';
import { ReviewWorkspace } from '@/components/ReviewWorkspace';
import { QuestionsView } from '@/components/QuestionsView';
import { EvidenceWorkspace } from '@/components/EvidenceWorkspace';
import { FindingsView } from '@/components/FindingsView';
import { ExportsView } from '@/components/ExportsView';
import { DetailInspectorModal } from '@/components/DetailInspectorModal';
import { DEMO_CLAIMS, DEMO_CONFLICTS, deriveMetrics } from '@/data/demoData';
import type {
  SecurityClaim,
  EvidenceNode,
  ConflictItem,
  LayerVisibility,
  NavItem,
} from '@/types/claimtrail';

type ActiveView = NavItem | 'overview';

export default function DashboardPage() {
  // ── Navigation
  const [currentView, setCurrentView] = useState<ActiveView>('overview');

  // ── Search
  const [searchQuery, setSearchQuery] = useState('');

  // ── Claim selection
  const [selectedClaimId, setSelectedClaimId] = useState('claim-1');
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>('node-repo-1');

  // ── Layer visibility (for Evidence graph)
  const [layers, setLayers] = useState<LayerVisibility>({
    policy: true,
    repository: true,
    controls: true,
    conflicts: true,
  });

  // ── Inspector modal
  const [isInspectorOpen, setIsInspectorOpen] = useState(false);
  const [inspectedNode, setInspectedNode] = useState<EvidenceNode | null>(null);

  // ── Evidence check simulation
  const [isRunningCheck, setIsRunningCheck] = useState(false);

  // ── Filtered Claims
  const filteredClaims = useMemo(() => {
    if (!searchQuery.trim()) return DEMO_CLAIMS;
    const q = searchQuery.toLowerCase();
    return DEMO_CLAIMS.filter(
      (c) =>
        c.code.toLowerCase().includes(q) ||
        c.question.toLowerCase().includes(q) ||
        c.category.toLowerCase().includes(q) ||
        c.primarySourcePath.toLowerCase().includes(q)
    );
  }, [searchQuery]);

  const activeClaim = useMemo(
    () => DEMO_CLAIMS.find((c) => c.id === selectedClaimId) ?? DEMO_CLAIMS[0],
    [selectedClaimId]
  );

  // ── Handlers
  function handleSelectClaim(claim: SecurityClaim) {
    setSelectedClaimId(claim.id);
    setSelectedNodeId(claim.nodes.length > 1 ? claim.nodes[1].id : (claim.nodes[0]?.id ?? null));
    if (currentView === 'overview') {
      setCurrentView('questions');
    }
  }

  function handleSelectNode(node: EvidenceNode) {
    setSelectedNodeId(node.id);
    setInspectedNode(node);
    setIsInspectorOpen(true);
  }

  function handleSelectConflictFromOverview(conflict: ConflictItem) {
    const claim = DEMO_CLAIMS.find((c) => c.code === conflict.claimCode);
    if (claim) {
      setSelectedClaimId(claim.id);
      const conflictNode = claim.nodes.find((n) => n.type === 'conflict');
      if (conflictNode) {
        setSelectedNodeId(conflictNode.id);
      }
    }
    setCurrentView('findings');
  }

  function handleSelectClaimForEvidence(claim: SecurityClaim) {
    setSelectedClaimId(claim.id);
    setSelectedNodeId(claim.nodes[0]?.id ?? null);
    setCurrentView('evidence');
  }

  function handleSelectFindingForEvidence(conflict: ConflictItem) {
    const claim = DEMO_CLAIMS.find((c) => c.code === conflict.claimCode);
    if (claim) {
      setSelectedClaimId(claim.id);
      const conflictNode = claim.nodes.find((n) => n.type === 'conflict');
      setSelectedNodeId(conflictNode?.id ?? claim.nodes[0]?.id ?? null);
    }
    setCurrentView('evidence');
  }

  function handleSelectClaimForQuestion(claimCode: string) {
    const claim = DEMO_CLAIMS.find((c) => c.code === claimCode);
    if (claim) {
      setSelectedClaimId(claim.id);
    }
    setSearchQuery(claimCode);
    setCurrentView('questions');
  }

  function handleOpenInspectorForClaim(claim: SecurityClaim) {
    setSelectedClaimId(claim.id);
    setInspectedNode(null);
    setIsInspectorOpen(true);
  }

  function handleLayerToggle(layer: keyof LayerVisibility) {
    setLayers((prev) => ({ ...prev, [layer]: !prev[layer] }));
  }

  function handleRunEvidenceCheck() {
    setIsRunningCheck(true);
    setTimeout(() => {
      setIsRunningCheck(false);
    }, 1800);
  }

  // ── Breadcrumb
  const breadcrumb = {
    overview: ['Dashboard', 'Overview'],
    review: ['Dashboard', 'Review & Pipeline'],
    questions: ['Dashboard', 'Questions'],
    evidence: ['Dashboard', 'Evidence Graph'],
    findings: ['Dashboard', 'Active Findings'],
    exports: ['Dashboard', 'Export & Attestation'],
  }[currentView];

  return (
    <div className="flex h-full w-full overflow-hidden bg-canvas">
      {/* ── Left Sidebar */}
      <AppSidebar currentNav={currentView} onNavChange={setCurrentView} />

      {/* ── Main Area */}
      <div className="flex-1 flex flex-col min-w-0 min-h-0 overflow-hidden">
        {/* Top Bar */}
        <AppTopBar
          breadcrumb={breadcrumb}
          searchQuery={searchQuery}
          onSearchChange={setSearchQuery}
          alertCount={DEMO_CONFLICTS.length}
          isRunningCheck={isRunningCheck}
          onRunEvidenceCheck={handleRunEvidenceCheck}
        />

        {/* ── View Router ── */}

        {/* 1. Overview Dashboard */}
        {currentView === 'overview' && (
          <OverviewDashboard
            claims={filteredClaims}
            conflicts={DEMO_CONFLICTS}
            selectedClaimId={selectedClaimId}
            onSelectClaim={handleSelectClaim}
            onSelectConflict={handleSelectConflictFromOverview}
            onViewAllQuestions={() => setCurrentView('questions')}
            onViewAllFindings={() => setCurrentView('findings')}
            onNavigateToReview={() => setCurrentView('review')}
            onNavigateToExports={() => setCurrentView('exports')}
          />
        )}

        {/* 2. Review Workspace (Pipeline & Logs) */}
        {currentView === 'review' && (
          <ReviewWorkspace
            claims={filteredClaims}
            conflicts={DEMO_CONFLICTS}
            isRunningCheck={isRunningCheck}
            onRunEvidenceCheck={handleRunEvidenceCheck}
            onNavigateToEvidence={() => setCurrentView('evidence')}
            onNavigateToQuestions={() => setCurrentView('questions')}
            onNavigateToFindings={() => setCurrentView('findings')}
          />
        )}

        {/* 3. Questions View (Row-by-Row Table) */}
        {currentView === 'questions' && (
          <QuestionsView
            claims={filteredClaims}
            conflicts={DEMO_CONFLICTS}
            onSelectClaimForEvidence={handleSelectClaimForEvidence}
            onSelectClaimForFinding={(c) => {
              handleSelectConflictFromOverview(c);
              setCurrentView('findings');
            }}
            onOpenInspector={handleOpenInspectorForClaim}
          />
        )}

        {/* 4. Evidence Workspace (Provenance Graph) */}
        {currentView === 'evidence' && (
          <div className="flex-1 flex flex-col min-h-0 min-w-0 overflow-hidden">
            {/* Evidence layer controls strip */}
            <div className="shrink-0 px-5 py-2 bg-surface border-b border-border flex flex-wrap items-center gap-4 text-xs text-text-secondary">
              <span className="font-medium text-text-primary shrink-0">Graph Layers:</span>
              {(
                [
                  { key: 'policy' as const, label: 'Policy Evidence' },
                  { key: 'repository' as const, label: 'Repository Evidence' },
                  { key: 'controls' as const, label: 'Security Controls' },
                  { key: 'conflicts' as const, label: 'Conflicts' },
                ] as const
              ).map(({ key, label }) => (
                <label key={key} className="flex items-center gap-1.5 cursor-pointer select-none">
                  <input
                    type="checkbox"
                    checked={layers[key]}
                    onChange={() => handleLayerToggle(key)}
                    className="w-3.5 h-3.5 accent-accent rounded"
                  />
                  <span className={layers[key] ? 'text-text-primary font-medium' : 'text-text-tertiary'}>
                    {label}
                  </span>
                </label>
              ))}
              <span className="ml-auto text-2xs font-mono text-signal-amber font-medium">
                PROVENANCE MAP · 4-STAGE TRACE
              </span>
            </div>

            {/* Claim selector tabs */}
            <div className="shrink-0 px-5 py-1.5 bg-surface border-b border-border flex items-center gap-2 overflow-x-auto">
              <span className="text-2xs font-mono uppercase tracking-wider text-text-tertiary shrink-0 mr-1">
                Claim:
              </span>
              {filteredClaims.map((c) => (
                <button
                  key={c.id}
                  onClick={() => {
                    setSelectedClaimId(c.id);
                    setSelectedNodeId(c.nodes[0]?.id ?? null);
                  }}
                  className={`shrink-0 text-xs font-mono px-2.5 py-1 rounded border transition-colors ${
                    c.id === selectedClaimId
                      ? 'border-accent bg-accent-bg text-accent font-semibold'
                      : 'border-border text-text-secondary hover:text-text-primary hover:border-border-strong'
                  }`}
                >
                  {c.code}
                </button>
              ))}
            </div>

            <EvidenceWorkspace
              claim={activeClaim}
              selectedNodeId={selectedNodeId}
              onSelectNode={handleSelectNode}
              layers={layers}
              onOpenInspector={() => {
                setInspectedNode(null);
                setIsInspectorOpen(true);
              }}
            />
          </div>
        )}

        {/* 5. Findings View (Investigation List & Detail) */}
        {currentView === 'findings' && (
          <FindingsView
            conflicts={DEMO_CONFLICTS}
            claims={DEMO_CLAIMS}
            onSelectFindingForEvidence={handleSelectFindingForEvidence}
            onSelectClaimForQuestion={handleSelectClaimForQuestion}
          />
        )}

        {/* 6. Exports View (Readiness & Attestation Packages) */}
        {currentView === 'exports' && (
          <ExportsView
            claims={DEMO_CLAIMS}
            conflicts={DEMO_CONFLICTS}
            onNavigateToFindings={() => setCurrentView('findings')}
            onNavigateToQuestions={() => setCurrentView('questions')}
          />
        )}
      </div>

      {/* ── Inspector Modal ── */}
      {isInspectorOpen && (
        <DetailInspectorModal
          claim={activeClaim}
          node={inspectedNode}
          onClose={() => setIsInspectorOpen(false)}
        />
      )}
    </div>
  );
}
