'use client';

import React from 'react';
import { Search, Bell, Play, RotateCw, ChevronDown, Check } from 'lucide-react';

interface AppTopBarProps {
  breadcrumb: string[];
  searchQuery: string;
  onSearchChange: (q: string) => void;
  alertCount: number;
  isRunningCheck: boolean;
  onRunEvidenceCheck: () => void;
  primaryActionLabel?: string;
  onPrimaryAction?: () => void;
}

export function AppTopBar({
  breadcrumb,
  searchQuery,
  onSearchChange,
  alertCount,
  isRunningCheck,
  onRunEvidenceCheck,
  primaryActionLabel,
  onPrimaryAction,
}: AppTopBarProps) {
  return (
    <header className="h-[52px] shrink-0 bg-surface border-b border-border flex items-center px-5 gap-3.5 select-none z-20">
      {/* Breadcrumb */}
      <div className="flex items-center gap-1.5 text-xs text-text-secondary min-w-0">
        {breadcrumb.map((crumb, i) => (
          <React.Fragment key={i}>
            {i > 0 && <span className="text-text-tertiary">/</span>}
            <span
              className={
                i === breadcrumb.length - 1
                  ? 'text-text-primary font-semibold'
                  : 'text-text-secondary hover:text-text-primary cursor-pointer transition-colors'
              }
            >
              {crumb}
            </span>
          </React.Fragment>
        ))}
      </div>

      {/* Project / Assessment Selector Pill */}
      <div className="hidden md:flex items-center gap-1 px-2.5 py-1 rounded border border-border bg-canvas/70 text-2xs text-text-secondary hover:text-text-primary cursor-pointer transition-colors ml-2">
        <span className="w-1.5 h-1.5 rounded-full bg-signal-green" />
        <span className="font-medium text-text-primary">Acme Corp</span>
        <span className="text-text-tertiary">·</span>
        <span className="font-mono text-3xs">SIG Lite 2026</span>
        <ChevronDown className="w-3 h-3 text-text-tertiary ml-0.5" />
      </div>

      {/* Spacer */}
      <div className="flex-1" />

      {/* Search */}
      <div className="relative w-44 lg:w-56">
        <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-text-tertiary pointer-events-none" />
        <input
          type="text"
          placeholder="Search controls..."
          value={searchQuery}
          onChange={(e) => onSearchChange(e.target.value)}
          className="w-full h-7 pl-8 pr-2.5 text-xs bg-canvas border border-border rounded placeholder:text-text-tertiary text-text-primary focus:outline-none focus:border-accent transition-all"
        />
      </div>

      {/* Alert Count Pill */}
      {alertCount > 0 && (
        <div
          className="flex items-center gap-1 px-2 py-1 rounded border border-signal-red-border/60 bg-signal-red-bg/50 text-signal-red text-2xs font-mono font-semibold"
          title={`${alertCount} active findings in assessment`}
        >
          <Bell className="w-3 h-3" />
          <span>{alertCount}</span>
        </div>
      )}

      {/* Primary Action Button */}
      <button
        onClick={onPrimaryAction || onRunEvidenceCheck}
        disabled={isRunningCheck}
        className="h-7 px-3 rounded bg-accent hover:bg-accent-hover text-white text-xs font-medium flex items-center gap-1.5 transition-colors disabled:opacity-60 disabled:cursor-not-allowed shrink-0 shadow-xs"
      >
        {isRunningCheck ? (
          <>
            <RotateCw className="w-3 h-3 animate-spin" />
            <span className="hidden sm:inline">Checking…</span>
          </>
        ) : (
          <>
            <Play className="w-3 h-3 fill-white" />
            <span>{primaryActionLabel || 'Run Evidence Check'}</span>
          </>
        )}
      </button>

      {/* User Avatar Placeholder */}
      <div
        className="w-7 h-7 rounded-full bg-canvas border border-border flex items-center justify-center text-3xs font-mono font-bold text-text-secondary shrink-0 cursor-pointer hover:border-border-strong transition-colors"
        title="Current Reviewer: Edwin B. (SecOps Admin)"
      >
        EB
      </div>
    </header>
  );
}
